string distribuir(int r, int b) {
    int grupos = b + 1;
    int base = r / grupos;
    int extras = r % grupos;

    string resposta;
    for (int i = 0; i < grupos; ++i) {
        int quantidade = base + (i < extras ? 1 : 0);
        resposta.append(quantidade, 'R');
        if (i < b) resposta += 'B';
    }
    return resposta;
}
